mapper.select:
select * from t_feedback user_id=#{userId}

   and solve=#{solve}

ORDER BY send_datetime desc

select a.feedback_id, a.user_id, a.content, a.solve, a.send_datetime, a.solve_datetime, a.reply, a.reply_datetime, b.username from t_Feedback a left join t_user b on a.user_id = b.user_id
a.solve=#{type}
ORDER BY a.send_datetime desc
